import type { Metadata } from 'next'
import { SignupForm } from '@/components/auth/SignupForm'

export const metadata: Metadata = {
  title: 'Create account',
}

export default function SignupPage() {
  return <SignupForm />
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { useKeyboardAware } from '@/hooks/useKeyboardAware'
import Link from 'next/link'
import { Typography } from '@/components/ui/typography'
import { zodResolver } from '@hookform/resolvers/zod'
import { useForm, useWatch } from 'react-hook-form'
import { z } from 'zod'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { createClient } from '@/lib/supabase/client'
import { cn } from '@/lib/utils'

const signupSchema = z.object({
  studioName: z.string().min(2, 'Studio name must be at least 2 characters').max(60),
  email: z.string().email('Enter a valid email'),
  password: z.string().min(8, 'Use 8 or more characters'),
})

type SignupValues = z.infer<typeof signupSchema>

function getPasswordStrength(password: string): { score: number; label: string } {
  if (!password) return { score: 0, label: '' }
  let score = 0
  if (password.length >= 8) score++
  if (/[A-Z]/.test(password)) score++
  if (/[0-9]/.test(password)) score++
  if (/[^A-Za-z0-9]/.test(password)) score++
  const labels = ['', 'Weak', 'Fair', 'Good', 'Strong']
  return { score, label: labels[score] ?? '' }
}

function PasswordStrengthBar({ password }: { password: string }) {
  const { score } = getPasswordStrength(password)
  if (!password) return null

  const widths = ['0%', '25%', '50%', '75%', '100%']
  const barColors = [
    '',
    'bg-destructive',
    'bg-warning',
    'bg-success',
    'bg-success',
  ]

  return (
    <div className="mt-1.5">
      <div className="h-1 w-full overflow-hidden rounded-full bg-border">
        <div
          className={cn('h-full rounded-full transition-all duration-300', barColors[score] ?? '')}
          style={{ width: widths[score] ?? '0%' }}
        />
      </div>
    </div>
  )
}

export function SignupForm() {
  useKeyboardAware()
  const router = useRouter()
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errorMessage, setErrorMessage] = useState<string>('')

  const {
    register,
    handleSubmit,
    control,
    formState: { errors },
  } = useForm<SignupValues>({
    resolver: zodResolver(signupSchema),
  })

  const passwordValue = useWatch({ control, name: 'password', defaultValue: '' })

  const onSubmit = handleSubmit(async (values) => {
    setIsSubmitting(true)
    setErrorMessage('')

    // Step 1: Create user + studio via server route (uses service-role for studio provisioning)
    const res = await fetch('/api/auth/signup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: values.email,
        password: values.password,
        studioName: values.studioName,
      }),
    })

    if (!res.ok) {
      const body = await res.json().catch(() => ({ error: 'Something went wrong' })) as { error?: string }
      setIsSubmitting(false)
      setErrorMessage(body.error ?? 'Signup failed — try again')
      return
    }

    // Step 2: Sign in client-side so browser has the session cookie
    const supabase = createClient()
    const { error: signInError } = await supabase.auth.signInWithPassword({
      email: values.email,
      password: values.password,
    })

    if (signInError) {
      setIsSubmitting(false)
      setErrorMessage('Account created but sign-in failed. Please go to login.')
      return
    }

    router.push('/onboarding')
    router.refresh()
  })

  const handleGoogleSignIn = async () => {
    const supabase = createClient()
    const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? window.location.origin
    await supabase.auth.signInWithOAuth({
      provider: 'google',
      options: {
        redirectTo: `${appUrl}/callback`,
      },
    })
  }

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-5">
      {/* Heading */}
      <div className="space-y-1">
        <Typography variant="h1" className="leading-tight">Set up your studio</Typography>
        <p className="text-sm text-muted-foreground">Try free. Cancel anytime.</p>
      </div>

      {/* Studio name */}
      <div className="space-y-1.5">
        <Label htmlFor="studioName">Studio name</Label>
        <Input
          id="studioName"
          type="text"
          autoComplete="organization"
          placeholder="Dark Matter Tattoo"
          aria-describedby={errors.studioName ? 'studio-name-error' : undefined}
          aria-invalid={!!errors.studioName}
          {...register('studioName')}
        />
        {errors.studioName && (
          <p id="studio-name-error" role="alert" className="text-xs text-destructive">
            {errors.studioName.message}
          </p>
        )}
      </div>

      {/* Email */}
      <div className="space-y-1.5">
        <Label htmlFor="email">Work email</Label>
        <Input
          id="email"
          type="email"
          autoComplete="email"
          placeholder="you@studio.com"
          aria-describedby={errors.email ? 'email-error' : undefined}
          aria-invalid={!!errors.email}
          {...register('email')}
        />
        {errors.email && (
          <p id="email-error" role="alert" className="text-xs text-destructive">
            {errors.email.message}
          </p>
        )}
      </div>

      {/* Password */}
      <div className="space-y-1.5">
        <Label htmlFor="password">Password</Label>
        <Input
          id="password"
          type="password"
          autoComplete="new-password"
          aria-describedby={errors.password ? 'password-error' : 'password-hint'}
          aria-invalid={!!errors.password}
          {...register('password')}
        />
        <PasswordStrengthBar password={passwordValue} />
        {errors.password ? (
          <p id="password-error" role="alert" className="text-xs text-destructive">
            {errors.password.message}
          </p>
        ) : (
          <p id="password-hint" className="text-xs text-muted-foreground">
            Use 8+ characters
          </p>
        )}
      </div>

      {/* Inline auth error */}
      {errorMessage && (
        <p role="alert" className="text-sm text-destructive">
          {errorMessage}
        </p>
      )}

      {/* Submit */}
      <Button
        type="submit"
        className="w-full h-10 font-semibold"
        loading={isSubmitting}
        loadingLabel="Creating studio…"
      >
        Create my studio
      </Button>

      {/* Divider */}
      <div className="relative">
        <div className="absolute inset-0 flex items-center">
          <span className="w-full border-t border-border" />
        </div>
        <div className="relative flex justify-center">
          <span className="bg-card px-3 text-xs text-muted-foreground">or continue with</span>
        </div>
      </div>

      {/* Google OAuth */}
      <Button
        type="button"
        variant="outline"
        className="w-full h-10"
        onClick={handleGoogleSignIn}
        aria-label="Continue with Google"
      >
        <svg className="mr-2 h-4 w-4" viewBox="0 0 24 24" aria-hidden="true">
          <path
            d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
            fill="#4285F4"
          />
          <path
            d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
            fill="#34A853"
          />
          <path
            d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
            fill="#FBBC05"
          />
          <path
            d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
            fill="#EA4335"
          />
        </svg>
        Continue with Google
      </Button>

      {/* Bottom links */}
      <p className="text-center text-sm text-muted-foreground">
        Already have an account?{' '}
        <Link href="/login" className="text-primary hover:underline underline-offset-2">
          Sign in
        </Link>
      </p>

      <p className="text-center text-xs text-muted-foreground">
        By signing up you agree to our{' '}
        <Link href="/terms" className="text-primary hover:underline underline-offset-2">
          Terms of Service
        </Link>{' '}
        and{' '}
        <Link href="/privacy" className="text-primary hover:underline underline-offset-2">
          Privacy Policy
        </Link>
      </p>
    </form>
  )
}

import type { Metadata } from 'next'
