export default async function OnboardingPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  // If studio already has a location → onboarding complete → go to dashboard
  const memberResult = await supabase
    .from('studio_members')
    .select('studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  const studioId = memberResult.data?.studio_id ?? null

  if (studioId) {
    const locResult = await supabase
      .from('locations')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)

    if ((locResult.count ?? 0) > 0) {
      redirect('/dashboard')
    }
  }

  return (
    <div className="w-full max-w-[520px]">
      <OnboardingWizard studioId={studioId} userId={user.id} />
    </div>
  )
}

