const bodySchema = z.object({
  email: z.string().email('Enter a valid email'),
  // QA #14: complexity + max length (bcrypt effective max is 72 bytes)
  password: z
    .string()
    .min(8, 'Password must be at least 8 characters')
    .max(72, 'Password must be 72 characters or fewer')
    .regex(
      /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/,
      'Password must include at least one uppercase letter, one lowercase letter, and one number',
    ),
  studioName: z.string().min(2, 'Studio name must be at least 2 characters').max(60),
})

export async function POST(request: NextRequest) {
  // Rate limit by IP
  const ip = getClientIp(request)

  const { success, limit, remaining } = await signupRatelimit.limit(ip)
  if (!success) {
    return new Response('Too many signup attempts. Try again later.', {
      status: 429,
      headers: {
        'Retry-After': '60',
        'X-RateLimit-Limit': String(limit),
        'X-RateLimit-Remaining': '0',
      },
    })
  }

  // Validate body
  const raw = await request.json().catch(() => null)
  const parsed = bodySchema.safeParse(raw)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.format() }, { status: 400 })
  }

