  // proved ownership by choosing a password. Re-enable email verification later via
  // a proper check-your-inbox flow once SMTP is wired up.
  const { data: userData, error: createError } = await admin.auth.admin.createUser({
    email: parsed.data.email,
    password: parsed.data.password,
    email_confirm: true,
    user_metadata: {
      studio_name: parsed.data.studioName,
      full_name: parsed.data.studioName,
    },
  })

  if (createError) {
    logger.warn({ ip, errorCode: createError.status, message: createError.message }, 'auth.signup.failed')
    return Response.json(
      { error: createError.message },
      {
        status: 400,
        headers: {
          'X-RateLimit-Limit': String(limit),
          'X-RateLimit-Remaining': String(remaining),
        },
      },
    )
  }

  const userId = userData.user?.id
  logger.info({ userId }, 'auth.signup.success')

  // Create studio + owner membership using service-role client (bypasses RLS).
